    display: flex;
    flex-wrap: wrap;
    gap: 12px;
    align-items: center;
    justify-content: center;
  }

  .btn-primary {
    display: inline-flex;
    align-items: center;
    gap: 10px;
    background: var(--color-spline-blue);
    color: var(--color-bright-white);
    font-family: var(--font-spline-sans);
    font-size: 16px;
    font-weight: 500;
    padding: 16px 24px;
    border-radius: 12px;
    border: none;
    cursor: pointer;
    text-decoration: none;
    white-space: nowrap;
    transition: opacity 0.2s;
  }

  .btn-primary:hover {
    opacity: 0.88;
  }

