    font-size: 16px;
    font-weight: 500;
    padding: 10px 20px;
    border-radius: 12px;
    border: none;
    cursor: pointer;
    text-decoration: none;
    white-space: nowrap;
    transition: background 0.2s;
  }

  .btn-secondary:hover {
    background: rgba(255, 255, 255, 0.22);
  }

